* { box-sizing: border-box; }
:root { --ink: #172554; --muted: #475569; --line: #e2e8f0; --surface: #fff; --accent: #1d4ed8; }
body { margin: 0; font: .95rem/1.5 system-ui, sans-serif; color: var(--ink); background: #f8fafc; }
.dashboard-shell { display: grid; grid-template-columns: 14rem minmax(0, 1fr); min-height: 100vh; }
.dashboard-sidebar { padding: 1.5rem 1rem; background: #0f172a; color: #e2e8f0; }
.brand { color: inherit; font-weight: 800; text-decoration: none; }
.dashboard-sidebar nav { display: grid; gap: .5rem; margin-block: 2rem; }
.dashboard-sidebar nav a { padding: .65rem .75rem; border-radius: .5rem; color: inherit; text-decoration: none; }
.dashboard-sidebar nav a[aria-current="page"] { background: #334155; }
.sidebar-note { color: #cbd5e1; font-size: .85rem; }
.dashboard-main { min-width: 0; padding: clamp(1rem, 3vw, 2rem); }
.dashboard-header { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 1rem; align-items: center; }
h1 { font-size: clamp(1.8rem, 4vw, 3rem); margin-block: .25rem; }
.eyebrow { color: var(--accent); font-size: .78rem; text-transform: uppercase; letter-spacing: .1em; font-weight: 800; }
.metric-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 1rem; margin-block: 1.5rem; }
.metric-card, .chart-panel, .data-panel { min-width: 0; padding: 1rem; border: 1px solid var(--line); border-radius: .75rem; background: var(--surface); }
.metric-card strong { display: block; font-size: clamp(1.4rem, 3vw, 2rem); overflow-wrap: anywhere; }
.metric-card p { color: var(--muted); margin-block: 0 .75rem; }
.trend { font-size: .8rem; } .trend-up { color: #166534; } .trend-down { color: #991b1b; }
.panel-heading { display: flex; justify-content: space-between; gap: 1rem; }
.chart-placeholder { display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); align-items: end; gap: .75rem; min-height: 13rem; padding: 1rem; border-radius: .5rem; background: repeating-linear-gradient(to bottom, #fff 0, #fff 3rem, #e2e8f0 3.05rem); }
.chart-bar { display: flex; justify-content: center; align-items: end; min-height: 2rem; height: var(--bar-height); background: #93c5fd; border-radius: .35rem .35rem 0 0; }
.chart-bar span { transform: translateY(1.5rem); font-size: .75rem; }
.bar-1 { --bar-height: 42%; } .bar-2 { --bar-height: 58%; } .bar-3 { --bar-height: 49%; } .bar-4 { --bar-height: 74%; } .bar-5 { --bar-height: 66%; } .bar-6 { --bar-height: 82%; } .bar-7 { --bar-height: 61%; }
.button { border: 1px solid var(--line); border-radius: .5rem; padding: .6rem .8rem; font: inherit; background: white; }
:focus-visible { outline: 3px solid #1d4ed8; outline-offset: 3px; }
@media (max-width: 68rem) { .metric-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (max-width: 46rem) { .dashboard-shell { grid-template-columns: 1fr; } .dashboard-sidebar nav { display: flex; flex-wrap: wrap; margin-block: 1rem; } .metric-grid { grid-template-columns: minmax(0, 1fr); } .chart-placeholder { gap: .25rem; padding-inline: .5rem; } }
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { scroll-behavior: auto !important; } }
